/** how many things each place needs for chapter c (the planner reserves spots for them) */
export function needs(c) {
  const C = CHAPTERS[c], n = { A: 0, B: 0, wild: 3, road: 0, town: 1, river: 0, house: 0 };
  for (const s of C.chain) {
    const t = s.get || s.use;
    if (t) n[t.at] = (n[t.at] || 0) + t.n;
  }
  n.house = Object.values(C.npcs).filter(p => p.at === 'house').length;
  return n;
}
